"use strict";const utils=require("./index");class TokenRefreshManager{constructor(){this.refreshInterval=null;this.REFRESH_INTERVAL_MS=24*60*60*1e3;this.SESSION_CHECK_INTERVAL_MS=6*60*60*1e3;this.lastRefresh=Date.now();this.lastSessionCheck=Date.now();this.failureCount=0;this.MAX_FAILURES=2;this.onSessionExpiry=null;this.sessionHealthCheckInterval=null;this._stopped=false;this._refreshInFlight=false}startAutoRefresh(ctx,defaultFuncs,fbLink){this._stopped=false;if(this.refreshInterval){clearTimeout(this.refreshInterval);this.refreshInterval=null}if(this.sessionHealthCheckInterval){clearInterval(this.sessionHealthCheckInterval);this.sessionHealthCheckInterval=null}const scheduleNext=()=>{if(this._stopped)return;const base=this.REFRESH_INTERVAL_MS;const jitter=Math.floor(base*(.2+Math.random()*.4));const interval=base+(Math.random()>.5?jitter:-jitter);this.refreshInterval=setTimeout(async()=>{if(this._stopped)return;if(this._refreshInFlight){scheduleNext();return}this._refreshInFlight=true;try{await this.refreshTokens(ctx,defaultFuncs,fbLink);utils.log("TokenRefresh","Tokens refreshed successfully")}catch(error){utils.error("TokenRefresh","Failed to refresh tokens:",error.message)}finally{this._refreshInFlight=false;scheduleNext()}},interval);this.refreshInterval.unref?.();utils.log("TokenRefresh",`Auto-refresh scheduled in ${interval}ms`)};this.sessionHealthCheckInterval=setInterval(async()=>{try{const isHealthy=await this.checkSessionHealth(ctx,defaultFuncs,fbLink);if(!isHealthy){utils.warn("TokenRefresh","Session health check failed, triggering refresh");if(this._refreshInFlight){utils.log("TokenRefresh","Refresh already in-flight, skipping health-check triggered refresh");return}this._refreshInFlight=true;try{await this.refreshTokens(ctx,defaultFuncs,fbLink)}finally{this._refreshInFlight=false}}}catch(error){utils.error("TokenRefresh","Session health check error:",error.message)}},this.SESSION_CHECK_INTERVAL_MS);this.sessionHealthCheckInterval.unref?.();scheduleNext()}async checkSessionHealth(ctx,defaultFuncs,fbLink){try{const probeUrl="https://www.facebook.com/ajax/presence/reconnect.php";const probeCtx={...ctx,_skipSessionInspect:true};const resp=await utils.get(probeUrl,ctx.jar,{reason:"reconnect",__a:1,__req:Math.floor(Math.random()*36**2).toString(36)},ctx.globalOptions,probeCtx);try{utils.saveCookies(ctx.jar)(resp)}catch(_){}const body=resp.body;if(!body)return false;const bodyStr=typeof body==="string"?body:JSON.stringify(body);const isLoginPage=bodyStr.includes('<form id="login_form"')||bodyStr.includes('id="loginbutton"');if(isLoginPage)return false;const isCheckpoint=bodyStr.includes('"checkpoint"')&&bodyStr.includes('"flow_type"');if(isCheckpoint)return false;this.lastSessionCheck=Date.now();return true}catch(error){const msg=error.message||"";if(msg.includes("Not logged in")||msg.includes("Session has expired")){utils.error("TokenRefresh","Session health check: session expired:",msg);return false}utils.warn("TokenRefresh","Session health check network error (ignoring):",msg);return true}}async refreshTokens(ctx,defaultFuncs,fbLink,retryCount=0){const MAX_RETRIES=3;const RETRY_DELAYS=[2e3,5e3,1e4];try{let resp=await utils.get(fbLink,ctx.jar,null,ctx.globalOptions,{noRef:true});utils.saveCookies(ctx.jar)(resp);let html=resp.body;if(!html){throw new Error("Empty response from Facebook")}const isLoginPage=html.includes('<form id="login_form"')||html.includes('id="loginbutton"')||html.includes('"login_page"')||html.includes('id="email" name="email"');const isCheckpoint=html.includes('"checkpoint"')&&html.includes('"flow_type"');if(isLoginPage||isCheckpoint){if(isCheckpoint){try{const{globalAntiSuspension:globalAntiSuspension}=require("./antiSuspension");(ctx.antiSuspension||globalAntiSuspension).tripCircuitBreaker("checkpoint_on_token_refresh",60*60*1e3)}catch(_){}}throw new Error("Session expired or checkpoint required")}const dtsgMatch=html.match(/"DTSGInitialData",\[],{"token":"([^"]+)"/);if(dtsgMatch){ctx.fb_dtsg=dtsgMatch[1];ctx.ttstamp="2";for(let i=0;i<ctx.fb_dtsg.length;i++){ctx.ttstamp+=ctx.fb_dtsg.charCodeAt(i)}ctx.jazoest=`2${Array.from(ctx.fb_dtsg).reduce((a,b)=>a+b.charCodeAt(0),0)}`}else{throw new Error("Failed to extract fb_dtsg token")}const lsdMatch=html.match(/"LSD",\[],{"token":"([^"]+)"/);if(lsdMatch){ctx.lsd=lsdMatch[1]}const jazoestMatch=html.match(/jazoest=(\d+)/);if(jazoestMatch){ctx.jazoest=jazoestMatch[1]}const revisionMatch=html.match(/"client_revision":(\d+)/);if(revisionMatch){ctx.__rev=revisionMatch[1]}const spinRMatch=html.match(/"__spin_r"\s*:\s*(\d+)/);const spinTMatch=html.match(/"__spin_t"\s*:\s*(\d+)/);if(spinRMatch)ctx.__spin_r=parseInt(spinRMatch[1],10);if(spinTMatch)ctx.__spin_t=parseInt(spinTMatch[1],10);this.lastRefresh=Date.now();this.failureCount=0;try{const autoReLoginManager=ctx&&ctx.autoReLoginManager;if(autoReLoginManager&&autoReLoginManager.isEnabled&&autoReLoginManager.isEnabled()){const appState=utils.getAppState(ctx.jar);autoReLoginManager.updateAppState(appState)}}catch(_){}return true}catch(error){this.failureCount++;utils.error("TokenRefresh",`Refresh failed (attempt ${retryCount+1}/${MAX_RETRIES+1}):`,error.message);if(this.failureCount>=this.MAX_FAILURES){utils.error("TokenRefresh",`Maximum failures (${this.MAX_FAILURES}) reached. Session may be expired.`);if(this.onSessionExpiry&&typeof this.onSessionExpiry==="function"){this.onSessionExpiry(error)}return false}if(retryCount<MAX_RETRIES){const delay=RETRY_DELAYS[retryCount];utils.log("TokenRefresh",`Retrying in ${delay}ms...`);await new Promise(resolve=>setTimeout(resolve,delay));return await this.refreshTokens(ctx,defaultFuncs,fbLink,retryCount+1)}return false}}stopAutoRefresh(){this._stopped=true;if(this.refreshInterval){clearTimeout(this.refreshInterval);this.refreshInterval=null;utils.log("TokenRefresh","Auto-refresh disabled")}if(this.sessionHealthCheckInterval){clearInterval(this.sessionHealthCheckInterval);this.sessionHealthCheckInterval=null;utils.log("TokenRefresh","Session health checks disabled")}}getTimeUntilNextRefresh(){if(!this.refreshInterval)return-1;return Math.max(0,this.REFRESH_INTERVAL_MS-(Date.now()-this.lastRefresh))}needsImmediateRefresh(){return Date.now()-this.lastRefresh>=this.REFRESH_INTERVAL_MS}setSessionExpiryCallback(callback){this.onSessionExpiry=callback}resetFailureCount(){this.failureCount=0}getFailureCount(){return this.failureCount}}module.exports={TokenRefreshManager:TokenRefreshManager};
